<?php require 'config.php';$q=trim($_GET['q']??'');$stmt=$db->prepare('SELECT id,name,email,course FROM students WHERE name LIKE CONCAT("%",?,"%") OR email LIKE CONCAT("%",?,"%") OR course LIKE CONCAT("%",?,"%") ORDER BY id DESC');$stmt->bind_param('sss',$q,$q,$q);$stmt->execute();$rows=$stmt->get_result();?><h1>Students</h1><form><input name="q" placeholder="Search name/email/course"><button>Search</button></form><form action="save.php" method="post"><input name="name" required placeholder="Name"><input name="email" type="email" required placeholder="Email"><input name="course" required placeholder="Course"><button>Add student</button></form><table><tr><th>Name</th><th>Email</th><th>Course</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['course'])?></td><td><a href="delete.php?id=<?=$r['id']?>" onclick="return confirm('Delete this student?')">Delete</a></td></tr><?php endwhile;?></table>